args<-commandArgs(TRUE);P<-normalizePath(args[1]);W<-file.path(P,'work/2026-10-29-journal-bulk-four');S<-file.path(W,'sources');PD<-file.path(P,'results/plot_data')
library(ggplot2);library(patchwork);library(grid);library(jsonlite)
wr<-function(x,f)write_json(x,f,pretty=TRUE,auto_unbox=TRUE,digits=NA)
putcsv<-function(x,key,suffix){f<-paste0('journal_',key,'_20261029_',suffix,'.csv');write.csv(x,file.path(PD,f),row.names=FALSE,na='');f}
rd<-function(f)read.csv(file.path(S,f),check.names=FALSE,stringsAsFactors=FALSE)
obj<-function(f){e<-new.env();load(file.path(S,paste0('ipop-',f)),e);e[[ls(e)[1]]]}
classes<-c('transcriptome','proteomics','metabolomics','cytokine','clinical_test','lipidomics','gut_microbiome','skin_microbiome','oral_microbiome','nasal_microbiome')
clabel<-c('Transcriptome','Proteome','Metabolome','Cytokines','Clinical tests','Lipidome','Gut microbiome','Skin microbiome','Oral microbiome','Nasal microbiome')
ocol<-setNames(c('#31A6A0','#E6AC46','#8E7DCA','#E97764','#6199CA','#D78BB4','#9DBB58','#D6A185','#689D83','#9399A2'),classes)
getclass<-function(ids){out<-rep(NA_character_,length(ids));for(k in classes)out[startsWith(ids,paste0(k,'_'))]<-k;stopifnot(!anyNA(out));out}
theme_set(theme_classic(base_family='Arial',base_size=7)+theme(axis.text=element_text(size=7,colour='#30343B'),axis.title=element_text(size=7),legend.text=element_text(size=7),legend.title=element_text(size=7),strip.text=element_text(size=7),plot.title=element_text(size=7,face='bold'),plot.tag=element_text(size=9,face='bold'),axis.line=element_line(linewidth=.25),axis.ticks=element_line(linewidth=.25),plot.margin=margin(3,3,3,3)))
saveplot<-function(p,key,width,height,files,qc){w<-file.path(W,key);saveRDS(p,file.path(w,'plot.rds'));wr(c(list(stem=paste0('journal_',key,'_20261029'),width_mm=width,height_mm=height,plot_data_files=files),qc),file.path(w,'input-qc.json'))}
# Nature Fig2c: final supplementary feature matrix + metadata; author column-normalize-then-sum logic.
features<-rd('reverse-Fig_2c_and_d.csv');meta<-rd('reverse-final-metadata.csv');stopifnot(!anyDuplicated(features$filename))
ba<-names(features)[-1];stopifnot(length(ba)==42,all(vapply(features[ba],function(x)all(x%in%c(0,1)),logical(1))))
joined<-merge(meta,features,by.x='sample_name',by.y='filename');animal<-joined[joined$SampleType=='animal',];stopifnot(nrow(animal)>0)
skin<-c('skin of body','skin of pes','skin of trunk','arm skin','head or neck skin','axilla skin');animal$UBERONBodyPartName[animal$UBERONBodyPartName%in%skin]<-'skin';animal$UBERONBodyPartName[animal$UBERONBodyPartName%in%c('blood serum','blood plasma')]<-'blood'
counts<-aggregate(animal[ba],list(tissue=animal$UBERONBodyPartName),sum);mat<-as.matrix(counts[ba]);den<-colSums(mat);prop<-sweep(mat,2,den,'/');prop[,den==0]<-0
tissues<-c('blood','caecum','colon','duodenum','feces','gall bladder','ileum','jejunum','liver','oral cavity','skin','stomach','upper digestive tract','urine');stopifnot(all(tissues%in%counts$tissue))
aa<-sub('_OH[23]$','',ba);oh<-as.integer(sub('.*_OH','',ba));aas<-rev(sort(unique(aa)));pdat<-data.frame(expand.grid(tissue=counts$tissue,ba=ba),fraction=as.vector(prop),count=as.vector(mat));pdat$aminoacid<-aa[match(pdat$ba,ba)];pdat$OH<-oh[match(pdat$ba,ba)]
sumprop<-aggregate(fraction~tissue+aminoacid,pdat,sum);sumprop<-sumprop[sumprop$tissue%in%tissues,];allcounts<-data.frame(ba=ba,aminoacid=aa,OH=oh,count=as.numeric(colSums(features[ba])));allcounts$log_count<-log1p(allcounts$count)
bfiles<-c(putcsv(pdat,'bile','all_tissue_fractions'),putcsv(sumprop,'bile','combined'),putcsv(allcounts,'bile','oh_counts'),putcsv(data.frame(ba=ba,denominator=den),'bile','denominators'))
saveRDS(list(tissues=tissues,aas=aas,combined=sumprop,counts=allcounts),file.path(W,'bile/data.rds'));saveplot(NULL,'bile',136,120,bfiles,list(source_rows=nrow(features),metadata_rows=nrow(meta),joined_rows=nrow(joined),animal_rows=nrow(animal),duplicate_metadata_names=sum(duplicated(meta$sample_name)),fraction_range=range(sumprop$fraction),palette=list(low='#F7F8F7',count_mid='#77CBB5',count_high='#357C9D',fraction_mid='#65C7B6',fraction_high='#27678D'),transform='OH counts use log1p; each BA normalized across all animal body sites then 2OH+3OH fractions summed. Not per-tissue sample prevalence.'))
# Nature Metabolism Fig3a,c,d,f: exact author clustering cut and mass-defect filters.
lipids<-rd('lipid-Supp._Table_8.csv')[,1:11];qtls<-rd('lipid-Supp._Table_9.csv');q<-merge(qtls,lipids);loc<-subset(q,qtl.chr=='1'&qtl.pos>169.2&qtl.pos<173.2);effects<-as.matrix(loc[,LETTERS[1:8]]);rownames(effects)<-loc$identifier;stopifnot(!anyDuplicated(rownames(effects)));hc<-hclust(dist(effects),method='complete');cut<-cutree(hc,h=1.5);selected<-names(cut[cut==1]);a<-subset(q,identifier%in%selected&qtl.chr=='1');a$KM<-a$mz*14/14.01565;a$KMD<-a$KM-floor(a$KM);a$KNM<-round(a$KM);ref<-a$KMD[a$class=='CE'][1]+.0134;a$RKMD<-(a$KMD-ref)/.0134;ce<-subset(a,class=='CE');rtmin<-mean(ce$rt)-3*sd(ce$rt);mzmin<-mean(ce$mz)-5*sd(ce$mz);mzmax<-mean(ce$mz)+5*sd(ce$mz);kd<-subset(a,class%in%c('CE','UNK')&rt>rtmin&mz>mzmin&mz<mzmax&abs(RKMD-round(RKMD))<.075);kd$identification<-ifelse(kd$id.status=='identified','Identified','Unidentified');a$display_class<-ifelse(a$id.status=='identified',a$category,'Unidentified');a$bubble_class<-ifelse(a$id.status=='identified'|a$category=='Fatty.Acyl',a$category,'Unidentified')
lcols<-c('Fatty.Acyl'='#E87A65','Glycerolipid'='#E4B640','Phospholipid'='#2BAA9B','Sphingolipid'='#9180C7','Sterol.Lipid'='#5A98CD','UNK'='#AFB5BC','Unidentified'='#AFB5BC');missing<-setdiff(unique(c(a$display_class,a$category,a$bubble_class)),names(lcols));if(length(missing))stop(paste('Unmapped lipid class',paste(missing,collapse=',')))
bars<-aggregate(identifier~subclass+category,a,length);names(bars)[3]<-'n';p1<-ggplot(a,aes(qtl.pos,qtl.lod,colour=display_class))+geom_point(size=1.35,alpha=.85)+scale_colour_manual(values=lcols)+labs(x='Chromosome 1 position (Mb)',y='LOD',title='Apoa2-associated lipid features',tag='a')+theme(legend.position='none')
p2<-ggplot(bars,aes(n,reorder(subclass,n),fill=category))+geom_col(width=.68,colour='#30343B',linewidth=.35)+scale_fill_manual(values=lcols)+scale_x_continuous(expand=expansion(mult=c(0,.06)))+labs(x='Lipid features',y=NULL,title='Lipid subclass composition',tag='c')+theme(legend.position='none')
p3<-ggplot(a[order(a$bubble_class!='Unidentified'),],aes(rt,mz,colour=bubble_class,size=qtl.lod))+geom_point(alpha=.8)+scale_colour_manual(values=lcols,breaks=names(lcols)[names(lcols)%in%unique(a$bubble_class)],labels=function(x)gsub('Glycerophospholipid','Glycerophospholipids',gsub('Fatty.Acyl','Fatty acyls',x,fixed=TRUE),fixed=TRUE))+scale_size_area(max_size=3.3,breaks=c(6,10,14))+labs(x='Retention time (min)',y='m/z',title='Chromatographic and mass coordinates',tag='d',colour=NULL,size='LOD')+guides(colour=guide_legend(nrow=2,override.aes=list(size=2)),size=guide_legend(nrow=1))+theme(legend.position='bottom',legend.box='vertical',legend.key.size=unit(2.5,'mm'),legend.spacing.y=unit(.3,'mm'))
p4<-ggplot(kd[order(kd$identification!='Unidentified'),],aes(KNM,RKMD,colour=identification))+geom_hline(yintercept=-6:0,colour='#E0E4E8',linewidth=.25)+geom_point(size=2,alpha=.9)+scale_colour_manual(values=c(Identified='#337DA6',Unidentified='#E89945'))+scale_y_continuous(breaks=-6:0)+coord_cartesian(ylim=c(-6.5,0))+labs(x='Kendrick nominal mass',y='Referenced mass defect',title='Cholesteryl ester candidate series',tag='f',colour=NULL)+theme(legend.position='bottom',legend.key.size=unit(3,'mm'))
known<-subset(kd,id.status=='identified'&RKMD>=-6.5&RKMD<=0);if(nrow(known)>0)p4<-p4+ggrepel::geom_text_repel(data=known,aes(label=analyte),size=7/ggplot2::.pt,family='Arial',seed=17,min.segment.length=0,box.padding=.25,show.legend=FALSE,max.overlaps=30,colour='#30343B')
lfiles<-c(putcsv(a,'lipid','selected_qtl'),putcsv(bars,'lipid','subclasses'),putcsv(kd,'lipid','kendrick'),putcsv(data.frame(identifier=loc$identifier,cluster=cut,effects),'lipid','allele_effects'))
saveplot((p1+p2)/(p3+p4)+plot_layout(heights=c(1,1.25)),'lipid',183,156,lfiles,list(source_lipids=nrow(lipids),source_qtls=nrow(qtls),locus_features=nrow(loc),selected_qtls=nrow(a),selected_features=length(unique(a$identifier)),kendrick_features=nrow(kd),kendrick_displayed=sum(kd$RKMD>=-6.5&kd$RKMD<=0),reference_CE=ref,thresholds=list(rt_min=rtmin,mz_min=mzmin,mz_max=mzmax,cut_height=1.5,RKMD=.075),palette=as.list(lcols),transform='Author complete-linkage Euclidean cut h=1.5; cluster1; Chr1. RKMD author RT lower bound only; no invented max-RT filter. Source code Figure2 maps published Figure3.'))
# Nature Aging Fig2b: author center, membership and correlation summaries.
center<-obj('center');fi<-obj('final_cluster_info');cr<-obj('cor_data');fi$class<-getclass(fi$variable_id);fi<-merge(fi,cr,by='variable_id',all.x=TRUE);stopifnot(!anyNA(fi$correlation),all(fi$membership>.5),nrow(center)==11,ncol(center)==91)
comp<-as.data.frame(table(cluster=factor(fi$cluster,levels=1:11),class=factor(fi$class,levels=classes)));names(comp)[3]<-'n';comp$fraction<-comp$n/as.numeric(table(factor(fi$cluster,levels=1:11)))[as.integer(comp$cluster)]
centers<-data.frame(cluster=rep(1:11,each=91),age=rep(as.numeric(names(center)),11),z=as.vector(t(as.matrix(center))));ord<-hclust(dist(center),method='complete');saveRDS(list(center=center,fi=fi,comp=comp,hc=ord,ocol=ocol,classes=classes,clabel=clabel),file.path(W,'clusters/data.rds'))
cfiles<-c(putcsv(centers,'clusters','centers'),putcsv(fi,'clusters','membership_correlations'),putcsv(comp,'clusters','composition'),putcsv(data.frame(order=seq_along(ord$order),cluster=ord$order),'clusters','row_order'))
saveplot(NULL,'clusters',183,128,cfiles,list(center_grid=c(11,91),membership_rows=nrow(fi),class_count=length(classes),display_age_step=2.5,palette=as.list(ocol),transform='Author stored membership-filtered centers reused. Complete Euclidean row ordering recomputed; heatmap samples 19 original columns at2.5-year steps; all91 values retained for the three selected center profiles. This is Fig2b adaptation, not individual trajectories of Fig2c.'))
# Nature Aging Fig4: counts from stored author q values. No inference is re-run.
base<-obj('temp_data');base$class<-getclass(base$variable_id);cuts<-c(.05,.01,.001,.0001);t<-do.call(rbind,lapply(cuts,function(v){d<-aggregate(base$p_value_adjust<v,list(age=base$center),function(x)sum(x,na.rm=TRUE));names(d)[2]<-'count';d$cutoff<-v;d}));wins<-do.call(rbind,lapply(c(15,20,25,30),function(v){d<-if(v==20)base else obj(paste0('temp_data_window',v));r<-aggregate(d$p_value_adjust<.05,list(age=d$center),function(x)sum(x,na.rm=TRUE));names(r)[2]<-'count';r$window<-v;r}));by<-aggregate(base$p_value_adjust<.05,list(age=base$center,class=base$class),function(x)sum(x,na.rm=TRUE));names(by)[3]<-'count';by$class<-factor(by$class,levels=classes)
pc<-c('#2A9E97','#648BCE','#A583C2','#E9AC4D');lineplot<-function(d,mapping)ggplot(d,mapping)+geom_line(linewidth=.55)+geom_point(size=.9)+scale_x_continuous(breaks=c(40,45,50,55,60,65))+scale_y_continuous(expand=expansion(mult=c(0,.07)))+labs(x='Age (years)',y='Differential features')
da<-lineplot(subset(t,cutoff==.05),aes(age,count))+geom_area(fill='#42B2A5',alpha=.16)+geom_line(colour='#289A91',linewidth=.65)+labs(title='All molecular features',tag='a');db<-lineplot(t,aes(age,count,colour=factor(cutoff),group=cutoff))+scale_colour_manual(values=rev(pc),labels=c('0.0001','0.001','0.01','0.05'))+labs(title='Adjusted P-value thresholds',tag='b',colour='q <')+guides(colour=guide_legend(nrow=2,byrow=TRUE))+theme(legend.position='bottom',legend.key.width=unit(3,'mm'),legend.text=element_text(size=7));dc<-lineplot(wins,aes(age,count,colour=factor(window),group=window))+scale_colour_manual(values=pc)+labs(title='Window-width sensitivity',tag='c',colour='Years')+guides(colour=guide_legend(nrow=2,byrow=TRUE))+theme(legend.position='bottom',legend.key.width=unit(3,'mm'),legend.text=element_text(size=7))
small<-lapply(seq_along(classes),function(i)lineplot(subset(by,class==classes[i]),aes(age,count))+geom_area(fill=ocol[i],alpha=.14)+geom_line(colour=ocol[i],linewidth=.6)+geom_point(colour=ocol[i],size=.8)+labs(title=clabel[i],x=if(i>5)'Age (years)'else NULL,y=if(i%in%c(1,6))'Differential features'else NULL,tag=if(i==1)'d'else NULL)+scale_x_continuous(breaks=c(40,50,60))+theme(plot.title=element_text(size=7,face='bold')))
dfiles<-c(putcsv(t,'deswan','thresholds'),putcsv(wins,'deswan','windows'),putcsv(by,'deswan','omics_counts'));saveplot((da+db+dc)/wrap_plots(small,ncol=5)+plot_layout(heights=c(1,1.75)),'deswan',183,160,dfiles,list(qvalue_rows=nrow(base),features=length(unique(base$variable_id)),centers=sort(unique(base$center)),missing_q=sum(is.na(base$p_value_adjust)),palette=as.list(ocol),transform='Strict author stored adjusted P-value < cutoff;sum over features;26windowcenters40..65;author window sizes15/20/25/30. Original DE-SWAN regressions not rerun.'))
